# =============================================================================
# Script: C_test_gcta_sex_differences.R
#
# Purpose:
#   Test for sex differences in GCTA REML variance component and heritability
#   estimates using Z-tests.
#
# Input:
#   - gcta_reml_results.rds: Combined results tibble generated by
#     A_read_gcta_logs.R.
#
# Outputs:
#   - A tibble containing female and male estimates, their standard errors,
#     Z-scores, and two-sided p-values for each tested parameter, stratified
#     by statin status and LDL-C phenotype.
#
# Methods:
#   - Calculates female–male differences for a user-specified parameter,
#     such as h2, Vp, VG, or Ve.
#   - Retrieves the corresponding standard errors automatically.
#   - Calculates Z-scores using the difference in estimates divided by the
#     square root of the sum of squared standard errors.
#   - Calculates two-sided p-values from the standard normal distribution.
#   - Supports testing multiple parameters and combining results into one
#     tibble.
#
# Dependencies:
#   - Requires results generated by A_read_gcta_logs.R and saved as
#     gcta_reml_results.rds.
#
# Notes:
#   - The Z-test assumes female and male estimates are independent.
#   - Run A_read_gcta_logs.R first to generate the required input file.
# =============================================================================

# =============================================================================
# 0. SETUP
# =============================================================================

library(tidyverse)
results <- readRDS("gcta_reml_results.rds")

# =============================================================================
# 1. FUNCTION: TEST SEX DIFFERENCES IN ESTIMATES
# =============================================================================

test_sex_difference <- function(results, parameter) {
  
  se_col <- paste0(parameter, "_SE")
  
  if (!parameter %in% names(results)) {
    stop("Estimate column not found: ", parameter)
  }
  
  if (!se_col %in% names(results)) {
    stop("Standard error column not found: ", se_col)
  }
  
  tmp <- results |>
    group_by(statin_status, ldl_type) |>
    summarise(
      estimate_fem = .data[[parameter]][sex == "fem"],
      se_fem = .data[[se_col]][sex == "fem"],
      estimate_male = .data[[parameter]][sex == "male"],
      se_male = .data[[se_col]][sex == "male"],
      .groups = "drop"
    ) |>
    mutate(
      z = (estimate_fem - estimate_male) /
        sqrt(se_fem^2 + se_male^2),
      p = 2 * pnorm(-abs(z)),
      parameter = parameter
    ) |>
    rename(
      estimate_female = estimate_fem
    )
  
  tmp
}

# =============================================================================
# 2. CALCULATE DIFFERENCES FOR EACH COMPONENT
# =============================================================================

# Heritability differences
test_sex_difference(results, "h2")

# Genetic variance differences
test_sex_difference(results, "VG")


# Residual variance differences
test_sex_difference(results, "Ve")

# Phenotypic variance differences
test_sex_difference(results, "Vp")

# =============================================================================
# 3. COMBINE AND DISPLAY
# =============================================================================

all_tests <- map_dfr(
  c("h2", "VG", "Ve", "Vp"),
  \(x) test_sex_difference(results, x)
)

all_tests